*****************************************************************			   **	       DrawIcon		   **	     Version 1.0		   **	   February 12, 1987	   **			   **			   ** (Not changed for version 2.0)		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1989	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   ***************************************************************************************************************************************** Change History** 18 May 88	Steven Glass** Icon Slice was modified to improve speed.** 3 March 89	Konstantin Othmer** Took out a few unnecessary instructions and don't call the shift routines* if we are shifting by zero. ** 15 May 89	Steven Glass** Took out calls to DeRefA and DeRefB.  This is done in line so there* is no need to link to the other segment.** 2-Oct-91	Dave Lyons** Made DrawIcon preserve DestPoint (PortRect), because it sets the* fastPort flag that says PortRect is valid.  This was causing problems* drawing icons in menu items.  Sometimes.***********************************************************************	include 'all.macros'	include 'special.macros'	include '::qd:qdequates:core.globals1'	include '::qd:qdequates:core.globals2'	include '::qd:qdequates:region.equs'	include '::qd:qdequates:slice.equs'	include '::qd:qdequates:qd.data.asm'	title 'QD Aux DrawIcon'; Equates from file	icon.asmMaskShiftTemp	equ ShiftTempImageShiftTemp	equ ZZEndOfSliceMaskPtr	equ ImageShiftTemp+2ImagePtr	equ MaskPtr+4ThisMask	equ ImagePtr+4ThisImage	equ ThisMask+2IconOpen	equ ThisImage+2IconSelected	equ IconOpen+2IconOffline	equ IconSelected+2ThisDither	equ IconOffline+2IconType	equ ThisDither+2ZZZEndOfExtra	equ IconType+2FG	equ TEMP2BG	equ TEMP2+2LightGrey	equ $3333; Equates from file	icon.asm proc/data area IconDATAm_Selected	equ 1m_Open	equ 2m_Offline	equ 4***************************************************	Imports	         ***************************************************	Import QDStart	Import BusyErr***************************************************	Entries	         ***************************************************	Entry InvertTable	Entry IconSlice	Entry ColorTable****************************************************************** DrawIcon**     PtrToIconData	    long*     IconMode	    word*     DestX	    integer*     DestY	    integer**** The icon data structure is as follows:** IconType     word	    Bit 15 is used to indicate whether the*	    icon image has color or black and white*	    information in it.  Setting bit 15 to one*	    implies that it	is a color icon and*	    cannot be colored otherwise.* IconSize     integer  This is the number of bytes in the image*	    and mask.* IconHeight   integer  This is height of the icon in pixels.* IconWidth    integer  This is the width of the icon in pixels.* IconImage    bytes    This is the icon image.  It is IconSize*	    bytes long.  Each row of pixels is*	    1+(IconWidth-1)/2 bytes wide.* MaskImage    bytes    This is the mask.  It is IconSize*	    bytes long.  Each row of pixels is*	    1+(IconWidth-1)/2 bytes wide.*** The display mode word has the following fields.** Bit 0        Set implies the icon is SELECTED.* Bit 1        Set implies the icon is OPEN.* Bit 2        Set implies the icon is OFF LINE.** Bits 3 - 7   Reserved* Bits 8 - 11  Foreground color to be applied to black part*              of the black and white icons.* Bits 12 - 15 Background color to be applied to the white*              part	of the black and white icons.*** When the mode word is zero, the icon is copied to the destination* through the specified mask.**      When bit 0 is set its image is inverted before copying.*      When bit 1 is set a light grey color pattern is copied.*      When bit 2 is set, the light grey pattern is ANDed to the image*           being copied.** All three of these operations can occur at once and the order the testing* occurs is**      Bit 1 (is it	open)*      Bit 2 (is it	offline)*      Bit 0 (is it	selected)** Color is only applied to the black and white icons if bits 8 thru 15* are not all zero.** Color inversion.	Colored pixels in an icon are inverted as follows:**      Black Pixels	become white.*      Any other color becomes black.********************************************************************	DSECT 0o_IconType	word	;info about the icono_IconSize	word	;Num bytes in imageo_IconHeight	word	;Num pixels tallo_IconWidth	word	;Num pixels wide (4	bits/pixel)o_IconImage	block 2	;ImageSize is how many bytes;o_IconMask    more	pixels	;ImageSize is how many bytes* The IconMode is defined as follows** bit 0     1 is selected, 0 is not* bit 1     1 is open, 0 is not* bit 2     1 is offline, 0 is not*DrawIcon	PROC EXPORT	DefineStackOrigDirect	wordRTL1	block 3RTL2	block 3DestY	wordDestX	wordIconMode	wordIconRecPtr	long;------------------------------------------------------;; Setup zp;	jsr QDStart;------------------------------------------------------;; The dest loc info	is from the current	graf port.	jsl PortLoc2ZP	; move dest info to	zp;***;*** added 2-Oct-91 DAL;***;*** Since we will destroy DestPoint (which equals PortRect),;*** and since PortLoc2ZP set the PortLocOK bit, we have to;*** mark it dirty again.;***;	phx;	ldx #512;	lda <DirtyDPFlags,x;	and #DrawStateBad;	sta <DirtyDPFlags,x;	plx;*** end 2-Oct-91*** added 2-Oct-91 DAL -- preserve DestPoint (PortRect)	phx	ldx #512	lda <DestPoint	sta <DrawIconTemp,x	lda <DestPoint+2	sta <DrawIconTemp+2,x	lda <DestPoint+4	sta <DrawIconTemp+4,x	lda <DestPoint+6	sta <DrawIconTemp+6,x	plx*** end 2-Oct-91;------------------------------------------------------;; Calculate the source rect using height and width.; Figure out the SrcWidth from IconWidth; Calculate the ImagePtr and the MaskPtr;	lda IconRecPtr,s	sta Temp2	lda IconRecPtr+2,s	sta Temp2+2	stz SrcRect	stz SrcRect+2	ldy #o_IconHeight	lda [Temp2],y	sta SrcRect+4	ldy #o_IconWidth	lda [Temp2],y	sta SrcRect+6	dec a	; take IconWidth in	pixels and	lsr a	; figure how many bytes wide it is	inc a	sta SrcWidth; if the destination is a 640 mode pixel map then double the; horizontal size.	bit DestSCB-1	bpl ModeIs320	asl SrcRect+6ModeIs320	moverect SrcRect,SrcBounds	lda DestSCB	; make these the same	sta SrcSCB	lda Temp2	clc	adc #o_IconImage	sta ImagePtr	lda Temp2+2	adc #0	sta ImagePtr+2	ldy #o_IconSize	clc	lda ImagePtr	adc [Temp2],y	sta MaskPtr	lda ImagePtr+2	adc #0	sta MaskPtr+2;------------------------------------------------------;; Get dest point off stack onto zp.;	lda DestY,s	sta DestPoint	lda DestX,s	sta DestPoint+2;----------------------------------------------------;; Extend the destpoint into a rectangle	of the same; size.;	lda SrcRect+4	clc	adc DestPoint	sta DestPoint+4	lda SrcRect+6	clc	adc DestPoint+2	sta DestPoint+6;----------------------------------------------------------;; Get Icon type	ldy #o_IconType	lda [Temp2],y	sta IconType;------------------------------------------------------;; Get transfer mode	from stack to zero page.;	lda IconMode,s	sta XFerMode	stz IconSelected	stz IconOpen	stz IconOffline	and #m_Selected	beq NotSelected	dec IconSelected	lda IconType	; if the icon is selected	ora #$8000	; we treat it as color and do not	sta IconType	; color it later on!notSelected	lda XferMode	and #m_Open	beq notOpen	dec IconOpen	lda IconType	; if the icon is open	ora #$8000	; we treat it as color and do not	sta IconType	; color it later on!notOpen	lda XferMode	and #m_Offline	beq notOffline	dec IconOfflinenotOffline	bit IconType	bmi ItsColor	lda XferMode	and #$FF00	bne ItsBW	lda IconType	ora #$8000	sta IconType	bra ItsColorItsBW	lda XferMode	xba	and #$000F	asl a	tax	lda >ColorTable,x	sta FG	lda XferMode	xba	and #$00F0	lsr a	lsr a	lsr a	tax	lda >ColorTable,x	sta BGItsColor;------------------------------------------------------;; Bring clip and vis rgn to zero page.;	jsl SetUpPortRegions	phb; Deref a and b	ldy #2	lda [RgnHandleA]	sta RgnPtrA	lda [RgnHandleA],y	sta RgnPtrA+2	lda [RgnHandleB]	sta RgnPtrB	lda [RgnHandleB],y	sta RgnPtrB+2	moverect DestRect,MinRect	jsl MakeMinRect	bcc SomethingLeft	jmp AllDoneSomethingLeft;-----------------------------------------------;; Now I check to see if the dest rect got; clipped.  If it did get clipped, then	I must; adjust the source	rect accordingly.	ldx #6AdjSrcLoop		;	lda MinRect,x	; I subtract DestRect from MinRect	sec	; If not clipped on	that side result	sbc DestRect,x	; is zero.  If clipped at top or left,	beq SideStillOK	; then result is positive and so is	clc	; amount src must be adjusted.  If	adc SrcRect,x	; clipped at bot or	right, then result	sta SrcRect,x	; is negative and so is amount srcSideStillOK	dex	; must be adjusted.	dex	bpl AdjSrcLoop;		; move clipped value of destrect;		; back to DestRect	MoveRect MinRect,DestRectNotSame	jsl ShieldCursor	; use minrect to shield cursor;-------------------------------------------------;; Set up the DestRef pointer.;	pha	; put room for result on stack	pha	lda DestRect	sec	sbc DestBounds	pha	pei DestWidth	_Multiply	pla	plx	clc	adc DestPixelMapRef	sta DestRef	txa	adc DestPixelMapRef+2	sta DestRef+2;----------------------------------------------------------;; Adjust the src pointers if necessary;	lda SrcRect	beq NoAdjust	tax	lda #0AddLoop	clc	adc SrcWidth	dex	bne AddLoop	tax	clc	adc ImagePtr	sta ImagePtr	bcc NoCarry1	inc ImagePtr+2NoCarry1	txa	clc	adc MaskPtr	sta MaskPtr	bcc NoCarry2	inc MaskPtr+2NoCarry2NoAdjust;-------------------------------------------------;; Set up looping vars, clipping and the	address; of the slice routine to be used.;	jsl SliceSetup	jsl SetUpScanPtrs	jsl Init2Regions	pei DestRef+1	; set the data bank	register to	plb	; bank containing dest map	plb	lda DestRect	sta CurrentY	ldx #$0FFF	and #1	beq Even	ldx #$FF0FEven	stx ThisDitherPaintLoop	jsl Seek2Regions	jsl IconSlice	lda CurrentY	; check to see if done	inc a	cmp DestRect+4	bpl TheEnd	; unsigned compare dummy 28 Mar 86	sta CurrentY	ldx #$0FFF	and #1	beq Even2	ldx #$FF0FEven2	stx ThisDither	lda SrcWidth	; bump the pointers	to source and	clc	; dest (accounting for carry)	adc ImagePtr	sta ImagePtr	bcc NoCarrySrc1	inc ImagePtr+2NoCarrySrc1	lda SrcWidth	clc	adc MaskPtr	sta MaskPtr	bcc NoCarrySrc2	inc MaskPtr+2NoCarrySrc2	lda DestWidth	clc	adc DestRef	sta DestRef	bcc NoCarryDest	inc DestRef+2	phb	; must also update the data bank	lda DestRef+1	; register	sta 0,s	plbNoCarryDest	bra PaintLoopTheEnd	jsl UnShieldCursorAllDone	jsl Free2Regions*** added 2-Oct-91 DAL -- restore DestPoint (PortRect)	ldx #512	lda <DrawIconTemp,x	sta <DestPoint	lda <DrawIconTemp+2,x	sta <DestPoint+2	lda <DrawIconTemp+4,x	sta <DestPoint+4	lda <DrawIconTemp+6,x	sta <DestPoint+6*** end 2-Oct-91 DAL	lda #0;;;NeverMind;;;ReportError	plb	tax	ldy #10	jmp BusyErr	ENDP****************************************************************** IconSlice** These are the lowest level pixel transfer routines.  They	copy* pixels from one scan line to another using an appropriate* transfer mode.** Parameters are passed on "ZeroPage" and in the overflow*   flag. (The overflow flag is used to	decide whether to*   invert the source--set for invert, clear for leave*   alone.)* A predraw routine	must set up "ZeroPage" and the overflow*   flag.** The routines do not use shift tables.	 Instead I use the two* shift subroutines.  This is faster than using shift tables* and working only a byte at a time.** The routines can handle scan lines as	long as 32K.  They do not* care about scan line width and will overflow into next scan line* if told to.** Change History** 18 May 88	Steven Glass** Minor modifications were made to the drawing routines to use* the faster method of drawing into a destination through a * mask (suggested by owen rubin).******************************************************************IconSlice	PROC EXPORT	stz MaskShiftTemp	; Zero these for later use	stz ImageShiftTemp	ldy DestStartWord	sty DestIndex	ldx SrcStartWord	stx SrcIndexLoopSkipMask;----------------------------------------------------------;; First create the current mask word by	shifting and merging; with MaskShiftTemp.;;------------------FAST ICON CHANGE--------------------------	ldx HowFarToShift	bne DoSlowWay	ldy SrcIndex	; Get source word from mask	lda [MaskPtr],y	sta ThisMask	lda [ImagePtr],y	sta ThisImage	bra SkipSlow;------------------------------------------------------------DoSlowWay	ldy SrcIndex	; Get source word from mask	lda [MaskPtr],y	sta ThisWord	; save for later	jsl vShiftOut	sta ShiftTemp2	; save it	lda ThisWord	jsl vShiftStay	ora MaskShiftTemp; Now do we do anything to the image word like invert or mask?	sta ThisMask	lda ShiftTemp2	; move this into position to be used	sta MaskShiftTemp	; next time;----------------------------------------------------------;; Now do the same with the image.;; Is Y still good here?  I think so.	lda [ImagePtr],y	sta ThisWord	; save for later	jsl vShiftOut	sta ShiftTemp2	; save it	lda ThisWord	jsl vShiftStay	ora ImageShiftTemp; Now do we do anything to the image word like invert or mask?	sta ThisImage	lda ShiftTemp2	; move this into position to be used	sta ImageShiftTemp	; next time.SkipSlow	iny	; bump Y now since it is in a register	iny	sty SrcIndex	ldy DestIndex	bmi BumpIndexes	; the special case again;----------------------------------------------------------;; This is where the	destination finally	gets changed!;; An icon can be;;     Not Selected or Selected;         Invert the image if selected;     Closed or Open;         For open,	Draw light gray pattern (Mac style) clipped to mask.;     Online or Offline;         for OffLine AND light gray pattern (Mac style) into image;; We copy the rotated image to the destination clipped to the; clipping region and the rotated mask.;	lda ThisImage	; get rotated image	in a-reg	bit IconOpen	; see if the icon is open	bpl NotOpen	lda #LightGrey	; it is open so switch light grayNotOpen		;	bit IconOffline	; see if on line	bpl NotOffLine	and ThisDither	; offline so AND in	the current ditherNotOffLine		;	bit IconSelected	; see if selected.	bpl NotSelected; invert the word as required	pha	; save word on stack	and #$00FF	; look at low byte	tax	; use as index into	inversion table	lda >InvertTable,x	and #$00FF	tay	; put result in Y	pla	; get orig word	xba	; look at high byte	and do same	and #$00FF	tax	lda >InvertTable,x	and #$00FF	xba	; put back in high byte	pha	; put on stack so can merge	tya	ora 1,s	ply	; clean stack	ldy DestIndex	; reset Y for use belowNotSelected		;; If this is a black and white icon, here is where I add the color.	bit IconType	bmi ItsColor	tax	; save copy in X	and BG	sta temp	txa	; back from x	eor #$FFFF	and FG	ora tempItsColor		;; Now copy into dest!	eor (DestRef),y	and ThisMask	and [ScanMaskref],y	eor (DestRef),y	sta (DestRef),y;----------------------------------------------------------;; Now I bump the indexes and decide if I'm done.;BumpIndexes		;	iny	iny	sty DestIndex	cpy DestFinishWord	beq DoAgain	bcs AllDoneDoAgain	brl LoopAllDone	rtl	ENDP*****************************************************************InvertTable	PROC EXPORT** This table is used to invert values in the icon image when* it is necessary to invert the image (ie it is selected).*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DC.B $ff,$f0,$f0,$f0,$f0,$f0,$f0,$f0,$f0,$f0,$f0,$f0,$f0,$f0,$f0,$f0	DC.B $0f,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	DC.B $0f,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	DC.B $0f,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	DC.B $0f,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	DC.B $0f,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	DC.B $0f,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	DC.B $0f,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	DC.B $0f,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	DC.B $0f,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	DC.B $0f,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	DC.B $0f,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	DC.B $0f,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	DC.B $0f,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	DC.B $0f,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	DC.B $0f,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	ENDP*****************************************************************ColorTable	PROC EXPORT** This table is used to convert a index between 0 and 15 into * a word that is has the index repeated in all four nibbles.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DC.B $00,$00	DC.B $11,$11	DC.B $22,$22	DC.B $33,$33	DC.B $44,$44	DC.B $55,$55	DC.B $66,$66	DC.B $77,$77	DC.B $88,$88	DC.B $99,$99	DC.B $aa,$aa	DC.B $bb,$bb	DC.B $cc,$cc	DC.B $dd,$dd	DC.B $ee,$ee	DC.B $ff,$ff	ENDP	END